const cds = require('../../../cds')
const { exists, read, yaml: YAML } = cds.utils
const { readProject } = require('../../projectReader')
const { merge } = require('../../merge')
const { srv4, enterpriseMessaging, xsuaa } = require('../../registries/mta')
const KymaTemplate = require('../kyma')

module.exports = class EnterpriseMessagingTemplate extends require('../../plugin') {
  constructor(...args) {
    super(...args)
    this._name = 'enterprise-messaging'
    this._kind = 'enterprise-messaging-http'
    this._vcap = 'enterprise-messaging'
    this._dirname = __dirname
    this._mta = enterpriseMessaging
  }

  static help() {
    return 'messaging via SAP Event Mesh'
  }

  options() {
    return {
      cloudevents: {
        type: 'boolean',
        short: 'c',
        help: 'Use CloudEvents formatting.'
      }
    }
  }

  async canRun() {
    const { isJava } = readProject()
    if (isJava) throw `'cds add ${this._name}' is not available for Java yet`
    return true
  }

  static hasInProduction(env) {
    const { kind = 'dummy', vcap } = env.requires?.messaging ?? {}
    return kind === this._kind && vcap?.label === this._vcap
  }

  async run() {
    const project = readProject()
    const { configFile, isNodejs } = project
    if (isNodejs) {
      project.shortcut = !exists(configFile) || typeof (await read(configFile)).cds?.requires?.messaging !== 'object'
      project.cloudevents = cds.cli.options.cloudevents
      await merge(this._dirname, 'files/package.json.hbs').into(configFile, { with: project })
    }
  }

  async combine(facet) {
    const project = readProject(facet)
    const { addXsuaa, hasXsuaa, addKyma, addMta, srv, appName } = project

    if (addMta) {
      const srvModule = srv4(srv.path)
      await merge(this._dirname, 'files/mta.yaml.hbs').into('mta.yaml', {
        project,
        additions: [srvModule, this._mta],
        relationships: [
          {
            insert: [this._mta, 'name'],
            into: [srvModule, 'requires', 'name']
          }
        ]
      })
    }

    if (addXsuaa || (addMta && hasXsuaa)) {
      if (addMta) {
        await merge(this._dirname, 'files/mta.yaml.hbs').into('mta.yaml', {
          project,
          additions: [xsuaa]
        })
        project['em-service-name'] = YAML.parse(await read('mta.yaml'))?.resources?.find(
          r => r?.parameters?.service === 'enterprise-messaging'
        )?.name
      } else {
        project['em-service-name'] = `${appName}-messaging`
      }
      await merge(this._dirname, 'files/xs-security.json.hbs').into('xs-security.json', {
        project,
        additions: [
          { in: 'scopes', where: { name: '$XSAPPNAME.emcallback' } },
          { in: 'scopes', where: { name: '$XSAPPNAME.emmanagement' } }
        ]
      })
    }

    if (addKyma) {
      await merge(this._dirname, 'files', 'values.yaml').into('chart/values.yaml')
      await KymaTemplate.mergeDependency('service-instance', 'event-mesh')
    }

    if (addKyma || addMta) await merge(this._dirname, 'files/event-mesh.json.hbs').into('event-mesh.json', { project })
  }
}
